c(1, "header lines 1-7", "positioning", "ShineDay: Habit Tracker / 小日常 (App Store ID 1263789061; subtitle 'Micro Habits, ADHD & Focus') by Guangzhou Xiaorichang Technology Co., Ltd. (bundle com.dandelion.Routine) — 20,634 written reviews, 48 storefronts, 3 Aug 2017 → 7 Sep 2026 (110 months), extracted 8 Sep 2026; written mean 4.25 (13,415×5★, 3,278×4★, 1,498×3★, 570×2★, 1,873×1★); ranking snapshot 562,951 public ratings at 4.78, ranked in 45 storefronts, best search rank 2 (Hong Kong), median rank 32, audience 'established'; a nine-year-old mainland-China habit tracker people choose for how it looks and feels (clean 8.32%, cute 6.94%, no social layer) whose reviews turn negative almost entirely over how it makes money", "freemium habit tracker: free habit quota, lifetime/membership tiers, 8-yuan ad-free SKU, ads from 2019 and aggressively from June 2025; also an Android build and a Mac build", "mixed", "20,634 reviews; 562,951 public ratings at 4.78", "none", "corpus-level fact", "app-specific", [])
c(2, "§How to read this; §1.1–1.5", "data-caveat", "Method: all 20,634 reviews read individually in original language (Chinese simplified and traditional, English, Japanese, mixed) in chronological order, 166 chunks of 125; hand-assigned from a 123-code, 12-family inductive taxonomy (Temp/52-cls, Temp/52-review-classification.py), 34,191 assignments (1.66 per review, median 1); validated 0 unknown IDs, 0 unassigned, 0 duplicate keys, 0 intra-review duplicate themes, 0 undefined codes, 1 declared-but-unused code (SOC_GROUP_NEG n=0); reconciliation exact against 48 by_country files, manifest (20,634; 5:13,415 · 4:3,278 · 3:1,498 · 2:570 · 1:1,873; mean 4.2500) and _state.json (92 storefronts polled, all complete); no deduplication — 171 identical title+body pairs over 953 records are coincidental short phrases (好 ×129, 不错 ×74, 好用 ×73, 很好 ×46, good ×16) and all kept; every global % divides by 20,634; signal bands <0.1% ignore · 0.1–0.5% weak · 0.5–1% emerging · 1–3% meaningful · 3–5% very strong · >5% high-priority; text sub-cuts only ever taken inside a hand-coded theme and labelled; high-impact clusters re-read before writing; no automated classifier; 13 fields present — author, app_id, app_name, country_name unused; is_edited 186 (0.90%), vote_count>0 on 323 (1.57%, max 63 on 5813993595), votes never weights; body median 19 characters, mean 34.9; translations marked EN", "n/a", "n/a", "20,634 (100%)", "none", "method statement", "app-specific", ["5813993595"])
c(3, "§Eight warnings 1, 7; §1.6 #4", "data-caveat", "A mainland-China corpus: 19,669 of 20,634 (95.32%) from cn and 19,858 (96.24%) written in Chinese — 'global' means China plus 965 reviews from 47 other storefronts; only six storefronts clear 50 (cn 19,669 · us 287 · tw 201 · hk 119 · ca 61 · au 53); gb 40, sg 27, jp 24, de 22 and every other storefront are limited evidence", "n/a", "n/a", "95.32% cn; 6 eligible storefronts", "none", "corpus-level fact", "app-specific", [])
c(4, "§Eight warnings 2; §1.6 #3", "data-caveat", "Written reviews are 3.67% of public ratings (20,634 of 562,951) and the written mean (4.25) sits 0.53★ below the public average (4.78) — a moderate gap consistent across storefronts, so a negativity-skewed sample, not a different population", "n/a", "n/a", "3.67%; −0.53★", "none", "corpus-level fact", "generalisable", [])
c(5, "§Eight warnings 3; §1.6 #6", "data-caveat", "Almost a quarter of the corpus has no product content: META_LOWINFO 4,760 (23.07%, largest theme, applied generously) — '好', '不错', '好用'; with pre-use and review-to-unlock reviews 5,479 (26.55%, mean 4.73) carry no product experience; median body 19 characters; the 5★ band is 30.8% content-free", "n/a", "n/a", "4,760 (23.07%); 5,479 (26.55%, 4.73); 5★ 30.8% content-free", "none", "corpus-level fact", "app-specific", [])
c(6, "§Eight warnings 4; §1.7 Review-to-unlock", "tactic", "Review-to-unlock gate at launch (2017): the app required a written review to unlock features — mostly reminders (132 of 462 name reminders) — with a length check; outcome: META_UNLOCK 462 (2.24%, meaningful, mean 4.16; 427 in 2017 = 16.0% of that year, 24 in 2018, 11 in 2019–2025); Oct–Dec 2017 holds 2,535 reviews (12.29% of the nine-year corpus), 415 unlock reviews (16.4% of the window); all 15 busiest days of 3,205 review days fall 5 Nov → 13 Dec 2017 (79, 70, 69, 63, 63… per day; peak 79 on 12 Dec 2017 = 0.38% of corpus); filler text — the title repeated twenty times, random character strings, '能不能不要逼人写评价啊' ('please stop forcing people to write reviews') repeated dozens of times at 5★; 'many gave five stars because a good review was required to keep using the app'; consequences: 2017 year mean 4.61 is the highest full year, 2017 is 48.6% low-info and 20.3% pre-use (542 of all 717 pre-use reviews), so 2017 is never used as a baseline for decline", "gated reminders behind writing a review, 2017", "5★-burst", "462 (2.24%, 4.16); 427 in 2017 (16.0%); 15 busiest days all Nov–Dec 2017; peak 79/day", "dont", "meaningful", "generalisable", ["1947016834","1958402990","1959643783","1901055265","2524800702"], side="inflates the 2017 mean and makes the launch year unusable as a baseline", cond="2017 launch; gate removed after 2017–2018")
c(7, "§Eight warnings 5; §1.7 Nth-launch prompts", "tactic", "From 2020 the app prompts for a review on the Nth launch ('第500次打开', '第800次打开', '第3000次打开') — solicited but not gated; 40 reviews mention the prompt (text census over the full corpus, mean 4.50); some complain: 'just downloaded, haven't used it, and it keeps asking me to review' (3★, 2020); 'paid 8 yuan to remove ads and it still insists I review' (3★, 2025) — solicitation inflates 5★ volume but does not change the direction of any finding", "Nth-launch review prompt, 2020–2026, also shown to paying ad-free buyers", "mixed", "40 mentions (mean 4.50)", "do", "text census", "generalisable", ["11090257717","11216871410","11350173560","11065176175","11285961475","6682921169","13351689320"], cond="milestone-launch prompt works when it fires after real use; fires too early for some and still fires for payers")
c(8, "§Eight warnings 6; §1.7 Contradictions", "data-caveat", "73 reviews (0.35%, weak) contradict their own rating — 35 are 5★ complaints and 24 are 1★ praise; kept and listed in full (§5.6, Appendix E)", "n/a", "n/a", "73 (0.35%): 35 5★ complaints, 24 1★ praise", "none", "weak", "app-specific", [])
c(9, "§Eight warnings 8; §1.6 #1, #2, #5, #7", "data-caveat", "No version field and no developer responses in the data: every release, price change and redesign is reconstructed from reviewer text and dates; no live App Store page or developer site fetched — every price, tier name, trial and feature description is reviewer-reported with reviewers' own errors, contradictions reported not resolved; one external source, the repo's undated habit_apps_ranked.json (public counts, averages, search ranks, market_tier rich/volume/other); reviewers mention developer replies (3823855755, 11719901468) but replies are not in the data; 2026 is partial (to 7 Sep); prices span nine years of changes", "n/a", "n/a", "report gives none", "none", "method statement", "app-specific", ["3823855755","11719901468"])
c(10, "§1.6 #8; §4.8", "contradiction", "The listing's 'ADHD' positioning is not a corpus theme: only 6 reviews (0.03%, ignore) mention ADHD — the store subtitle ('Micro Habits, ADHD & Focus') and the reviewing population do not overlap", "subtitle names ADHD", "none", "6 (0.03%)", "research", "ignore", "app-specific", [], cond="Chinese-language user base; ADHD keyword aimed at English search")
c(11, "§1.7 Fake-review allegations", "data-caveat", "META_FAKE 37 (0.18%, weak, mean 2.27): mostly 1★ reviewers who cannot reconcile the high average with their experience ('such a high score must be bought'); no evidence of purchased reviews beyond the disclosed 2017 gate", "n/a", "complaint", "37 (0.18%, 2.27)", "none", "weak", "generalisable", ["12841963125","3761234905"])

