c(12, "§Part 0 executive summary; §0.9 #1", "timeline", "The 2025 ad rollout is the largest negative event in nine years: AD_NEG 885 (4.29%, very strong, mean 2.46; 1/2/3/4/5 = 383/103/139/128/132; 2018-12-27 → 2026-09-04, cn×864), 575 of 885 (65.0%) written in 2025 alone; Jan–May 2025 991 reviews, 6 AD_NEG (0.6%), mean 4.59 → Jun–Nov 2025 1,562 reviews, 546 AD_NEG (35.0%), mean 3.70 → 2026 (to 7 Sep) 1,341, 78 (5.8%), mean 4.42; July 2025 is the lowest-rated month in the corpus (362 reviews, mean 3.35; 173 AD_NEG), June 2025 next (3.60); before 2025 the lowest month was Dec 2019 (3.61); monthly means recovered to 4.45–4.61 Jan–May 2026 — whether mechanics were softened or complainants left, the corpus cannot distinguish", "aggressive ads from June 2025", "1★-burst", "885 (4.29%, 2.46); Jun–Nov 2025 546/1,562 = 35.0% at 3.70; Jul 2025 3.35", "dont", "very strong", "generalisable", ["12831040911","13362003467","12795677855","12743825635"])
c(13, "§0.1 table (verbatim)", "timeline", "Ad rollout window table (verbatim)", "n/a", "n/a", table("## 0.1 The 2025 ad rollout", 0), "none", "table", "app-specific", [])
c(14, "§0.1 mechanics table (verbatim) and reading", "anti-pattern", "Reviewers do not object to ads as such; they describe specific interaction-design mechanics, repeatedly and independently — text sub-cuts inside AD_NEG, 2025–26: ad opens another app automatically (Taobao, Pinduoduo, Meituan, Quark) 107; close / skip button hidden, tiny or ineffective 88; shaking or tilting the phone triggers the ad 33; ad appears after the check-in itself, not only at launch (read in window); paying members still see ads (AD_NEG ∩ PAY_BOUGHT, all years) 40 — 'the skip and close buttons get more hidden… move the phone slightly, twist it, tilt the screen… it jumps into the ad page'; a full-screen Taobao ad 'that also can't be closed'; the reading: 'the ads were not a pricing decision that users rejected. They were an interaction-design decision' — a 35% complaint rate within five months", "auto-jump ads, motion-triggered ads, close control that does not close, ads after check-in, ads to payers", "1★-burst", table("## 0.1 The 2025 ad rollout", 1), "dont", "very strong", "generalisable", ["12831040911","12886873169","12914673906","13362003467","12803944732","12793111376","12829168869","12739880901","12796570816","12742750263"])
c(15, "§0.1 bullet; §0.9 #1", "must-never-break", "Paying members still see ads — 40 reviews AD_NEG ∩ PAY_BOUGHT (all years): 'I bought lifetime membership before… now there are too many ads, an ugly ad pops up at every check-in' (1★, Jun 2025); the decision: never show ads after a check-in or to any payer", "lifetime and ad-free buyers shown ads, including on check-in", "1★-burst", "40 reviews", "must-never-break", "very strong (parent theme)", "generalisable", ["12795677855","14301818772","13876926025","4189381643"])
c(16, "§0.1 bullets; §0.9 #1", "monetization", "An 8-yuan lifetime ad-free SKU exists; reviewers who find it accept the trade ('but 8 yuan removes ads forever', 5★; 'paid 8 yuan, much better', 5★) while others conclude the ads exist to sell it ('noticed the 8-yuan lifetime ad-free SKU and concludes the ads exist to sell it', 1★) — the decision: surface the 8-yuan ad-free SKU honestly", "paid: 8 yuan one-time ad removal", "mixed", "report gives none (quotes only)", "undecided", "very strong (parent theme)", "generalisable", ["13284916834","14100445684","13362003467"], cond="cheap one-time ad removal is accepted when discoverable; aggressive ads make it read as extortion")
c(17, "§0.1 quotes", "audience", "Ads contradict the calm purpose of the product and hit vulnerable users: a two-year user 'ads contradict the app's purpose of calming you down. Sorry, uninstalled' (3★, us storefront, Chinese text, Jun 2025); a chronic-illness patient logging medication says the growing ads are 'agitating for a patient' (1★, Oct 2025)", "ads in a calm self-care app", "churn", "report gives none", "dont", "very strong (parent theme)", "generalisable", ["12743825635","13229374881"])
c(18, "§0.1 last paragraph", "timeline", "Ads were not new in 2025: splash ads for Ctrip (2019) and Pinduoduo (2021) produced a smaller wave — AD_NEG 99 reviews (3.4%) in 2020, 83 (2.8%) in 2021, then 0.2–0.7% in 2022–2024; a 2022 reviewer even tells others to downgrade to v5.05 to escape ads", "splash ads 2019–2021", "complaint", "2020 99 (3.4%); 2021 83 (2.8%); 2022–24 0.2–0.7%", "dont", "very strong (parent theme)", "app-specific", ["4607325416","7038818912","8329654441"])
c(19, "§0.2", "monetization", "The free habit quota is the persistent monetisation friction and the first wall a new user meets: PAY_CAP5 888 (4.30%, very strong, mean 2.96; 1/2/3/4/5 = 257/98/154/180/199); PAY_WALL 715 (3.47%, very strong, mean 2.62); monetisation-friction union 2,496 (12.10%, high-priority, mean 2.98); 'only five free habits is too few… anyone serious wants to keep more than five things a day' (5★, Dec 2017) and the same complaint in 2020 and 2025, eight years apart", "free: capped habit quota (5 most often stated)", "complaint", "PAY_CAP5 888 (4.30%, 2.96); PAY_WALL 715 (3.47%, 2.62); union 2,496 (12.10%, 2.98)", "build-free", "very strong", "generalisable", ["2001609740","5519779697","12892816707"])
c(20, "§0.2 bullet 'The stated cap moved'", "data-caveat", "The stated cap moved: inside PAY_CAP5/PAY_WALL reviewers name '5 habits' in every year 2018–2025 (174 mentions, text sub-cut) but also '4' (2017–2018, 2020–2024), '3' (2020–2021, 2025), '6' (2018), '8' (2025) and '10' (2020, 2021, 2025, 2026) — reviewers are describing different builds and cohorts", "cap changed across builds and cohorts", "mixed", "174 '5 habits' mentions; 4 / 3 / 6 / 8 / 10 also stated", "none", "text sub-cut", "app-specific", ["13289981450","14081265840"])
c(21, "§0.2 bullet 'From 2025 the quota grows with use'", "tactic", "From 2025 the free habit quota grows with use — 'keep checking in and it gives you more habit slots' (5★); 'I thought it was capped at 8, then found it grows with use' (4★); 'very kind' (5★) — reviewers who notice treat it as generosity, not friction; outcome: PAY_CAP5 fell from 8.2% of reviews (2018) and 7.1% (2020) to 0.6% in 2026, the only monetisation theme with a sustained, monotonic decline", "free quota earned through continued check-ins (2025 on)", "praise", "PAY_CAP5 8.2% (2018) → 7.1% (2020) → 0.6% (2026)", "build-free", "very strong (parent theme)", "generalisable", ["13125235029","13289981450","13591116003"], side="turns the cap from a wall into a reward loop", cond="observed from 2025; the decline may also reflect cohort change")
c(22, "§0.2 bullet 'iOS quota was tighter than Android's'", "market", "The iOS quota was tighter than Android's and switchers noticed: 'on Android I could add a dozen, why treat us differently?' (1★, 2019)", "iOS free quota smaller than Android's", "complaint", "report gives none", "dont", "very strong (parent theme)", "generalisable", ["3853033716"], cond="cross-platform app with different per-platform limits")
c(23, "§0.3; §6.1", "insight", "Paying users are the most satisfied segment — until an entitlement breaks: PAY_BOUGHT 1,286 (6.23%, high-priority, mean 4.11; 815 at 5★ = 63.4% segment rate); 199 (15.5% segment rate) explicitly bought lifetime, mean 4.36; why people pay (lift = segment rate ÷ global rate): PAY_PRICE_OK 5.7% vs 1.24% ×4.58, SOC_NOSOCIAL 2.6% vs 0.58% ×4.55, DEV_TRUST 4.0% vs 1.03% ×3.92, DES_THEME 6.1% vs 1.66% ×3.65, DES_ICON_WANT 7.7% vs 2.72% ×2.83; what goes wrong after: SUP_BAD 4.0% vs 0.89% ×4.53, PAY_TIERS 2.8% vs 0.55% ×5.11, REM_FAIL 4.9% vs 1.35% ×3.62, PAY_RESTORE 3.0% vs 0.92% ×3.21", "paid: lifetime and membership tiers", "purchase-driver", table("## 0.3 Paying users", 0), "must-never-break", "high-priority", "generalisable", [])
c(24, "§0.3 payer sub-segment table (verbatim)", "insight", "Once an entitlement or reliability failure happens, payers become the harshest reviewers: paid and reports value (fair price, trust, clean/cute, outcome) at 4–5★ n=306 mean 4.92; paid and an entitlement broke (restore / billing / refund / regression / price rise) 80 at 2.62; paid and a reliability failure (crash, lag, update, data loss, sync, widget, reminder) 286 at 3.04; paid and data loss 33 at 1.73; paid and support never answered 52 at 1.92", "n/a", "mixed", table("## 0.3 Paying users", 1), "must-never-break", "high-priority", "generalisable", [])
c(25, "§0.3 'The single most expensive failure is the reinstall path'; §0.9 #2", "anti-pattern", "The single most expensive failure is the reinstall path: a crash leads to a reinstall, which loses local data; restoring that data asks for membership, and the old membership doesn't restore — 32 reviews say outright that restoring their own data required paying: 'after reinstalling I bought lifetime membership to restore my data, and restoring crashed the app' (1★, 26 Sep 2024); decision: never put restoring a user's own records behind a paywall", "data restore gated behind membership; membership restore fails after reinstall", "1★-burst", "32 reviews", "product-rule", "high-priority (parent)", "generalisable", ["6494333470","11779820068","11764810805"], side="turns a crash into a forced purchase and a data-loss 1★")
c(26, "§0.4", "must-never-break", "Memberships don't travel across devices or platforms: PAY_RESTORE 190 (0.92%, emerging, mean 2.61); DATA_SYNC_FAIL 151 (0.73%, emerging, 3.23); PLAT_ANDROID 195 (0.95%, emerging, 3.53); PLAT_MAC 37 (0.18%, weak, 3.81); data integrity union (loss, sync failure or restore failure) 518 (2.51%, meaningful, mean 2.85); decision: one account owns the membership and the data across iPhone, iPad, Mac and Android", "membership bound per platform; restore unreliable", "complaint", "PAY_RESTORE 190 (0.92%, 2.61); union 518 (2.51%, 2.85)", "must-never-break", "meaningful", "generalisable", ["6663079686","12506637899"])
c(27, "§0.4 bullet Android ↔ iOS", "monetization", "The membership is sold twice across Android and iOS, at different prices, with different login methods (QQ on Android versus WeChat on iOS): 49 reviews combine PLAT_ANDROID with a tier or restore failure (mean 2.80); 'only after buying did I find Android membership must be bought separately' (1★, 2023); 'iOS lifetime 88, Android 48? Where's the justice' (1★, Feb 2026)", "paid separately per platform; iOS lifetime 88 vs Android 48", "complaint", "49 reviews (2.80)", "dont", "emerging", "generalisable", ["4353672876","6367540210","8198718685","10530140312","13791604447"])
c(28, "§0.4 bullet iPhone ↔ iPad", "must-never-break", "iPhone ↔ iPad: 147 reviews combine PLAT_IPAD with sync failure, a sync request or a restore failure (0.71%, emerging); an iPhone membership isn't recognised on iPad (2020); a lifetime member reports two years of sync complaints across several feedback channels with no reply (1★, 2025)", "iPad does not honour iPhone membership; iPad sync unreliable", "complaint", "147 (0.71%)", "must-never-break", "emerging", "generalisable", ["6663079686","12506637899"])
