c(37, "§0.7; §0.9 #5", "market", "The international users literally cannot read the app: LOC_UNTRANS 153 globally (0.74%, emerging, mean 3.25) but 100 of 453 reviews from English-primary storefronts (22.1% segment rate, mean 3.00) say notifications, pop-ups, prompts and ads remain in Chinese with the device set to English; in each eligible non-Chinese storefront it is the single largest theme — us 64/287 (22.30%), ca 14/61 (22.95%), au 11/53 (20.75%), high-priority at country denominator; Taiwan's equivalent: LOC_WANT 46/201 (22.89%, high-priority) for missing Traditional Chinese; public average there still 4.65–4.74, so not sinking the listing, but named by almost every fourth non-Chinese reviewer; decision: finish English and Traditional Chinese strings, starting with notifications and ads", "partial English localisation; no Traditional Chinese", "complaint", "us 64/287 (22.30%); ca 14/61 (22.95%); au 11/53 (20.75%); tw LOC_WANT 46/201 (22.89%)", "do", "high-priority (country denominators)", "generalisable", ["3000754446","6448767945","5222510620"])
c(38, "§0.7 quote 11313989030", "insight", "Untranslated UI plus a precise-location permission request made a US reviewer conclude the app was malware — titled 'Malware?? DO NOT INSTALL' (1★, 2024); a Canadian 'I'd give 4 or 5 stars' if everything were in English (1★, 2019) — a rating contradiction caused purely by localisation", "Chinese strings in English UI + location permission", "1★-burst", "n=2 quotes", "do", "emerging", "generalisable", ["11313989030","5222510620"])
c(39, "§0.8 Outcomes; §3.4 P3", "insight", "Reported real-world outcomes: 1,340 reviews (6.49%, high-priority, mean 4.88) — self-discipline OUT_DISCIPLINE 761 (3.69%), less procrastination 107, fitness 190, study 115, mental health 57; 'to push my depressed self to do the small daily things' (5★, Dec 2025); 'this app helped me quit smoking for 577 days' (5★, Apr 2026)", "n/a", "praise", "1,340 (6.49%, 4.88)", "none", "high-priority", "generalisable", ["13578778405","13925038009"])
c(40, "§0.8 Tenure", "insight", "Tenure is rising: USER_LONGTERM 705 (3.42%, very strong, mean 4.63); 460 of these (65.2%) written in 2024–2026, when long-tenure users were 8.1%, 6.7% and 8.5% of each year's reviews; 'eight years of yoga logged… my 2,000th check-in' (5★, Aug 2026)", "n/a", "praise", "705 (3.42%, 4.63); 2024/25/26 8.1% / 6.7% / 8.5%", "none", "very strong", "generalisable", ["14460751570"])
c(41, "§0.8 DEV_TRUST; §3.4 P4", "product-rule", "Honoured lifetime purchases build unusual loyalty: DEV_TRUST 213 (1.03%, meaningful, mean 4.93 — the highest-mean theme above 100 reviews); 'I thought I'd have to pay again, but it said: you are a lifetime member. I nearly cried' (5★, 2021, reinstalled years later)", "lifetime membership honoured years later", "praise", "213 (1.03%, 4.93)", "product-rule", "meaningful", "generalisable", ["8082408412"])
c(42, "§0.8 STAT_REWARD; §3.4 P5", "feature", "Reward mechanics are liked and growing: STAT_REWARD (光芒值 'sunshine points' earned by check-ins and exchanged for self-set rewards) 312 (1.51%, meaningful, mean 4.65), rising from 0.1–0.8% of reviews before 2021 to 1.9–3.1% from 2021 on", "free: points exchanged for self-set rewards", "praise", "312 (1.51%, 4.65); <2021 0.1–0.8% → 2021+ 1.9–3.1%", "build-free", "meaningful", "generalisable", [])
c(43, "§0.9 (five decisions)", "insight", "The five decisions this corpus supports: 1 fix the ad mechanics, not the ad model (remove motion-triggered and auto-jump ads, make close close, no ads after check-in or to payers, surface the 8-yuan SKU honestly); 2 one account owns membership and data across iPhone, iPad, Mac and Android, and restoring a user's own records is never paywalled; 3 a release gate in front of old-iOS devices and data migrations (six waves = 42.5% of crash reviews, at least three destroyed data); 4 ship new UI as opt-in and never remove one-tap check-in; 5 finish English and Traditional Chinese strings, starting with notifications and ads", "n/a", "n/a", "report gives none beyond cited sections", "product-rule", "report's decisions", "generalisable", [])
